     // Add to your existing Trip form buttons
frm.add_custom_button(__('🔍 Debug OCR File'), function() {
    let d = new frappe.ui.Dialog({
        title: __('Debug OCR Processing'),
        size: 'large', // Use large size for better content display
        fields: [
            {
                label: __('Select Image File'),
                fieldname: 'debug_file',
                fieldtype: 'Attach Image',
                reqd: 1,
                description: __('Select a government ID or passport image to test OCR extraction')
            }
        ],
        primary_action_label: __('Run OCR Debug'),
        primary_action: function(values) {
            // Show loading state
            d.get_primary_btn().text(__('Processing...')).prop('disabled', true);
            
            frappe.call({
                method: 'tms.utils.ocr_api.debug_single_file',
                args: {
                    file_url: values.debug_file
                },
                freeze: true,
                freeze_message: __('Processing image with OCR...'),
                callback: function(r) {
                    // Reset button state
                    d.get_primary_btn().text(__('Run OCR Debug')).prop('disabled', false);
                    
                    if (r.message.success) {
                        // Create organized results display
                        let debug_html = createDebugResultsHTML(r.message);
                        
                        frappe.msgprint({
                            title: __('OCR Debug Results - Success ✅'),
                            indicator: 'green',
                            message: debug_html
                        });
                    } else {
                        frappe.msgprint({
                            title: __('OCR Debug Failed ❌'),
                            indicator: 'red',
                            message: __(`Error: ${r.message.error}`)
                        });
                    }
                },
                error: function() {
                    // Handle call failure
                    d.get_primary_btn().text(__('Run OCR Debug')).prop('disabled', false);
                    frappe.msgprint({
                        title: __('API Call Failed'),
                        indicator: 'red',
                        message: __('Failed to connect to OCR service. Please try again.')
                    });
                }
            });
        }
    });
    
    // Add secondary action to clear/close
    d.set_secondary_action_label(__('Cancel'));
    d.get_secondary_btn().on('click', function() {
        d.hide();
    });
    
    d.show();
}, __("OCR Tools"));

// Helper function to create organized results HTML
function createDebugResultsHTML(data) {
    return `
        <div style="max-height: 600px; overflow-y: auto; font-family: monospace;">
            <div style="margin-bottom: 15px; padding: 10px; background: #f8f9fa; border-radius: 5px;">
                <strong>OCR Engine:</strong> ${data.ocr_engine || 'N/A'} | 
                <strong>Text Length:</strong> ${data.text_length || 0} characters
            </div>
            
            <div style="margin-bottom: 15px;">
                <h4 style="color: #2e7d32; margin-bottom: 8px;">📋 Extracted Passenger Data</h4>
                <pre style="background: #f5f5f5; padding: 10px; border-radius: 3px; border-left: 4px solid #2e7d32;">${JSON.stringify(data.passenger_data || {}, null, 2)}</pre>
            </div>
            
            ${data.formatted_lines && data.formatted_lines.length > 0 ? `
            <div style="margin-bottom: 15px;">
                <h4 style="color: #1565c0; margin-bottom: 8px;">📄 Document Structure</h4>
                <pre style="background: #f5f5f5; padding: 10px; border-radius: 3px; border-left: 4px solid #1565c0; max-height: 200px; overflow-y: auto;">${data.formatted_lines.join('\n')}</pre>
            </div>
            ` : ''}
            
            ${data.full_text ? `
            <div style="margin-bottom: 15px;">
                <h4 style="color: #7b1fa2; margin-bottom: 8px;">🔍 Full Raw Text</h4>
                <details>
                    <summary style="cursor: pointer; color: #7b1fa2; margin-bottom: 5px;">Click to expand raw OCR text</summary>
                    <pre style="background: #f5f5f5; padding: 10px; border-radius: 3px; border-left: 4px solid #7b1fa2; font-size: 10px; max-height: 300px; overflow-y: auto; white-space: pre-wrap;">${data.full_text}</pre>
                </details>
            </div>
            ` : ''}
        </div>
    `;
}

