frappe.ui.form.on('Trip', {
    refresh: function(frm) {
        // Add main OCR processing button
        frm.add_custom_button(__('🚀 Process IDs with OCR'), function() {
            processTripOCR(frm);
        }, __("OCR Tools"));

        // Add debug button
        frm.add_custom_button(__('🔍 Debug OCR File'), function() {
            debugSingleFile(frm);
        }, __("OCR Tools"));

        // Add quick test button
        frm.add_custom_button(__('🧪 Quick OCR Test'), function() {
            quickOCRTest(frm);
        }, __("OCR Tools"));
    }
});

// Main OCR Processing Function
function processTripOCR(frm) {
    frappe.confirm(
        __('Process all attached ID images and auto-fill passenger data?'),
        function() {
            // Yes button - Process OCR
            frappe.call({
                method: 'tms.utils.ocr_api.process_passengers_batch',
                args: {
                    trip_name: frm.doc.name,
                    use_openai: false  // Set to true if you want to use OpenAI
                },
                freeze: true,
                freeze_message: __('Processing ID images with OCR...'),
                callback: function(r) {
                    if (r.message.success) {
                        frappe.show_alert({
                            message: __(r.message.message),
                            indicator: 'green'
                        });
                        
                        // Show detailed results
                        showOCRResults(r.message.details);
                        
                        // Refresh the form to show new passengers in child table
                        frm.refresh();
                        
                    } else {
                        frappe.show_alert({
                            message: __(r.message.message || 'OCR processing failed'),
                            indicator: 'red'
                        });
                        
                        if (r.message.details) {
                            showOCRResults(r.message.details);
                        }
                    }
                }
            });
        },
        function() {
            // No button
            frappe.show_alert({message: __('Cancelled'), indicator: 'red'});
        }
    );
}

// Function to display OCR processing results
function showOCRResults(details) {
    if (!details || details.length === 0) return;
    
    let results_html = `
        <div style="max-height: 400px; overflow-y: auto;">
            <h4>📊 OCR Processing Results</h4>
            <table class="table table-bordered" style="font-size: 12px;">
                <thead>
                    <tr>
                        <th>File</th>
                        <th>Status</th>
                        <th>Details</th>
                    </tr>
                </thead>
                <tbody>
    `;
    
    details.forEach(item => {
        results_html += `
            <tr>
                <td style="max-width: 150px; overflow: hidden; text-overflow: ellipsis;">
                    ${item.file || 'N/A'}
                </td>
                <td>
                    <span class="indicator ${item.status === 'success' ? 'green' : item.status === 'failed' ? 'orange' : 'red'}">
                        ${item.status || 'unknown'}
                    </span>
                </td>
                <td>
        `;
        
        if (item.status === 'success') {
            results_html += `✅ Added: ${item.passenger} (${item.engine})`;
        } else if (item.status === 'failed') {
            results_html += `❌ ${item.reason || 'Unknown error'} ${item.engine ? '(' + item.engine + ')' : ''}`;
        } else if (item.status === 'error') {
            results_html += `💥 ${item.reason || 'Unknown error'}`;
        }
        
        results_html += `</td></tr>`;
    });
    
    results_html += `</tbody></table></div>`;
    
    frappe.msgprint({
        title: __('OCR Processing Complete'),
        indicator: 'green',
        message: results_html
    });
}

// Debug Single File Function
function debugSingleFile(frm) {
    let d = new frappe.ui.Dialog({
        title: __('Debug OCR Processing'),
        fields: [
            {
                label: __('Select Image File'),
                fieldname: 'debug_file',
                fieldtype: 'Attach Image',
                reqd: 1,
                description: __('Select a government ID or passport image to test OCR extraction')
            }
        ],
        primary_action_label: __('Run OCR Debug'),
        primary_action: function(values) {
            d.get_primary_btn().text(__('Processing...')).prop('disabled', true);
            
            frappe.call({
                method: 'tms.utils.ocr_api.debug_single_file',
                args: {
                    file_url: values.debug_file
                },
                freeze: true,
                freeze_message: __('Processing image with OCR...'),
                callback: function(r) {
                    d.get_primary_btn().text(__('Run OCR Debug')).prop('disabled', false);
                    
                    if (r.message.success) {
                        let debug_html = createDebugResultsHTML(r.message);
                        
                        frappe.msgprint({
                            title: __('OCR Debug Results - Success ✅'),
                            indicator: 'green',
                            message: debug_html
                        });
                    } else {
                        frappe.msgprint({
                            title: __('OCR Debug Failed ❌'),
                            indicator: 'red',
                            message: __(`Error: ${r.message.error}`)
                        });
                    }
                }
            });
        }
    });
    
    d.set_secondary_action_label(__('Cancel'));
    d.get_secondary_btn().on('click', function() { d.hide(); });
    d.show();
}

// Quick OCR Test Function
function quickOCRTest(frm) {
    frappe.prompt({
        label: 'Select Test Image',
        fieldname: 'test_file',
        fieldtype: 'Attach Image',
        reqd: 1,
        description: 'Test OCR on a single file to see extracted data'
    }, (values) => {
        frappe.show_alert({
            message: __('Starting OCR test...'),
            indicator: 'blue'
        });
        
        frappe.call({
            method: 'tms.utils.ocr_api.debug_single_file',
            args: { file_url: values.test_file },
            callback: function(r) {
                if (r.message.success) {
                    frappe.show_alert({
                        message: __('OCR test completed successfully!'),
                        indicator: 'green'
                    });
                    
                    // Ask user if they want to add this passenger to the trip
                    if (r.message.passenger_data && r.message.passenger_data.name) {
                        frappe.confirm(
                            __(`Add passenger "${r.message.passenger_data.name}" to this trip?`),
                            function() {
                                // Yes - Add to child table
                                addPassengerToTrip(frm, r.message.passenger_data);
                            },
                            function() {
                                // No - Just show results
                                let debug_html = createDebugResultsHTML(r.message);
                                frappe.msgprint({
                                    title: __('OCR Test Results'),
                                    indicator: 'green',
                                    message: debug_html
                                });
                            }
                        );
                    } else {
                        let debug_html = createDebugResultsHTML(r.message);
                        frappe.msgprint({
                            title: __('OCR Test Results'),
                            indicator: 'orange',
                            message: debug_html
                        });
                    }
                } else {
                    frappe.show_alert({
                        message: __('OCR test failed: ') + (r.message.error || 'Unknown error'),
                        indicator: 'red'
                    });
                }
            }
        });
    }, __('Quick OCR Test'), __('Test'));
}

// Function to manually add passenger to child table
function addPassengerToTrip(frm, passenger_data) {
    // Add new row to child table
    var child = frm.add_child('passengers');
    
    // Fill the fields with extracted data
    frappe.model.set_value(child.doctype, child.name, 'passenger_name', passenger_data.name || '');
    frappe.model.set_value(child.doctype, child.name, 'idpassport_no', passenger_data.id_no || '');
    frappe.model.set_value(child.doctype, child.name, 'nationality', passenger_data.nationality || '');
    
    // Refresh the child table
    frm.fields_dict.passengers.grid.refresh();
    
    // Save the form
    frm.save();
    
    frappe.show_alert({
        message: __('✅ Passenger added to trip successfully!'),
        indicator: 'green'
    });
}

