frappe.ui.form.on('Trip', {
    refresh: function(frm) {
        // Add OCR buttons to the form (only for saved trips)
        if (!frm.doc.__islocal) {
            // Main OCR button
            frm.add_custom_button(__('🔍 Process Attachments with OCR'), function() {
                frm.events.process_attachments(frm);
            }).addClass('btn-primary');
            
            // Single file upload button
            frm.add_custom_button(__('📄 Scan Single ID'), function() {
                frm.events.upload_and_scan(frm);
            });
            
            // Show OCR status
            frm.events.show_ocr_status(frm);
        }
        
        // Listen for auto-processing events
        frm.events.setup_ocr_listeners(frm);
    },
    
    setup_ocr_listeners: function(frm) {
        // Listen for real-time OCR processing events
        frappe.realtime.on('ocr_processed', function(data) {
            if (frm.doc.name === data.trip) {
                frappe.show_alert({
                    message: __(`Auto-OCR: Added passenger "${data.passenger_added}" (Confidence: ${data.confidence}%)`),
                    indicator: 'blue'
                });
                frm.reload_doc();
            }
        });
    },
    
    process_attachments: function(frm) {
        // Use document method instead of module path
        frappe.call({
            method: 'extract_passengers_tesseract',
            doc: frm.doc,
            args: {
                file_urls: null // Process all attachments
            },
            callback: function(r) {
                if (r.message && r.message.success) {
                    var added = r.message.passengers_added || 0;
                    frappe.show_alert({
                        message: __(`OCR processed successfully! Added ${added} passengers`),
                        indicator: 'green'
                    });
                    
                    // Reload the form to show new passengers
                    frm.reload_doc();
                    
                    // Show detailed results if available
                    if (r.message.details) {
                        frm.events.show_ocr_results(frm, r.message.details);
                    }
                } else {
                    var error_msg = r.message ? r.message.message : 'OCR processing failed';
                    frappe.msgprint({
                        title: __('OCR Processing Failed'),
                        message: error_msg,
                        indicator: 'red'
                    });
                }
            }
        });
    },
    
    upload_and_scan: function(frm) {
        var dialog = new frappe.ui.Dialog({
            title: __('Upload ID/Passport for OCR'),
            fields: [
                {
                    fieldname: 'image_upload',
                    fieldtype: 'Attach Image',
                    label: __('Select ID/Passport Image'),
                    reqd: 1
                },
                {
                    fieldname: 'auto_process',
                    fieldtype: 'Check',
                    label: __('Auto-process future similar images'),
                    default: 1
                }
            ],
            primary_action_label: __('Scan and Add Passenger'),
            primary_action: function() {
                var file_url = dialog.get_value('image_upload');
                if (file_url) {
                    dialog.hide();
                    frm.events.scan_single_file(frm, file_url);
                }
            }
        });
        
        dialog.show();
    },
    
    scan_single_file: function(frm, file_url) {
        frappe.call({
            method: 'add_passenger_from_ocr',
            doc: frm.doc,
            args: {
                file_url: file_url
            },
            callback: function(r) {
                if (r.message && r.message.success) {
                    frappe.show_alert({
                        message: __(`Passenger "${r.message.passenger_added}" added successfully (Confidence: ${r.message.confidence}%)`),
                        indicator: 'green'
                    });
                    frm.reload_doc();
                } else {
                    frappe.msgprint({
                        title: __('OCR Scan Failed'),
                        message: r.message ? r.message.message : 'Could not extract passenger data',
                        indicator: 'red'
                    });
                }
            }
        });
    },
    
    show_ocr_status: function(frm) {
        // Show OCR learning statistics in sidebar
        frappe.call({
            method: 'get_ocr_learning_stats',
            doc: frm.doc,
            callback: function(r) {
                if (r.message && !r.message.error) {
                    var stats = r.message;
                    var status_html = `
                        <div class="ocr-status" style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 4px; padding: 15px; margin: 10px 0;">
                            <h6 style="margin-bottom: 10px; color: #2e5fa9; border-bottom: 1px solid #dee2e6; padding-bottom: 5px;">OCR Learning Progress</h6>
                            <div style="margin: 5px 0; font-size: 12px;">Name Patterns: ${stats.name_patterns || 0}</div>
                            <div style="margin: 5px 0; font-size: 12px;">ID Patterns: ${stats.id_patterns || 0}</div>
                            <div style="margin: 5px 0; font-size: 12px;">Nationality Patterns: ${stats.nationality_patterns || 0}</div>
                            <div style="margin: 5px 0; font-size: 12px;">Corrections Learned: ${stats.corrections || 0}</div>
                        </div>
                    `;
                    
                    // Add to form sidebar
                    var route_field = frm.fields_dict.route;
                    if (route_field && route_field.wrapper && !frm.ocr_status_wrapper) {
                        frm.ocr_status_wrapper = $(status_html).appendTo(route_field.wrapper);
                    }
                }
            }
        });
    },
    
    show_ocr_results: function(frm, details) {
        var results_html = `<div class="ocr-results" style="max-height: 400px; overflow-y: auto;"><h6>OCR Processing Details:</h6>`;
        
        details.forEach(function(result, index) {
            var status = result.success ? '✅ Success' : '❌ Failed';
            var confidence = result.success ? `<br/>Confidence: ${result.data.structured_data.confidence || 0}%` : '';
            results_html += `
                <div class="result-item" style="padding: 8px; margin: 5px 0; border: 1px solid #e9ecef; border-radius: 4px; background: #f8f9fa;">
                    <strong>File ${index + 1}:</strong> ${status}${confidence}<br/>
                    ${result.success ? `Name: ${result.data.structured_data.name}` : `Error: ${result.error}`}
                </div>
            `;
        });
        
        results_html += `</div>`;
        
        frappe.msgprint({
            title: __('OCR Processing Results'),
            message: results_html,
            wide: true
        });
    }
});

