frappe.ui.form.on('Trip', {
    auto_check_attachments: function(frm) {
        // Check if there are attachments but no passengers
        if (frm.doc.passengers && frm.doc.passengers.length === 0) {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'File',
                    filters: {
                        attached_to_doctype: 'Trip',
                        attached_to_name: frm.doc.name
                    },
                    fields: ['file_url', 'file_type']
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        var image_files = r.message.filter(function(file) {
                            return file.file_type && file.file_type.startsWith('image/');
                        });
                        
                        if (image_files.length > 0) {
                            // Ask user if they want to auto-process
                            frappe.confirm(
                                __('Found ' + image_files.length + ' image attachment(s). Would you like to automatically extract passenger information using OCR?'),
                                function() {
                                    // Yes - process attachments
                                    frm.events.process_attachments(frm);
                                },
                                function() {
                                    // No - do nothing
                                }
                            );
                        }
                    }
                }
            });
        }
    }
});

