frappe.ui.form.on('Trip', {
    refresh: function(frm) {
        // ... existing code ...
        
        if (!frm.doc.__islocal) {
            // Add verify OCR button
            frm.add_custom_button(__('✏️ Verify OCR Results'), function() {
                frm.events.show_ocr_verification(frm);
            });
        }
    },
    
    show_ocr_verification: function(frm) {
        // Show dialog to verify and correct OCR results
        var fields = [];
        
        frm.doc.passengers.forEach(function(passenger, index) {
            fields.push(
                {
                    fieldname: 'passenger_' + index + '_name',
                    fieldtype: 'Data',
                    label: __('Passenger ') + (index + 1) + __(' Name'),
                    default: passenger.passenger_name,
                    reqd: 1
                },
                {
                    fieldname: 'passenger_' + index + '_id',
                    fieldtype: 'Data', 
                    label: __('ID/Passport No'),
                    default: passenger.idpassport_no
                },
                {
                    fieldname: 'passenger_' + index + '_nationality', 
                    fieldtype: 'Data',
                    label: __('Nationality'),
                    default: passenger.nationality
                },
                {fieldtype: 'Section Break', label: __('')}
            );
        });
        
        var dialog = new frappe.ui.Dialog({
            title: __('Verify and Correct OCR Results'),
            fields: fields,
            primary_action_label: __('Save Corrections'),
            primary_action: function() {
                var corrections = [];
                frm.doc.passengers.forEach(function(passenger, index) {
                    var corrected_name = dialog.get_value('passenger_' + index + '_name');
                    var corrected_id = dialog.get_value('passenger_' + index + '_id');
                    var corrected_nationality = dialog.get_value('passenger_' + index + '_nationality');
                    
                    if (corrected_name !== passenger.passenger_name || 
                        corrected_id !== passenger.idpassport_no || 
                        corrected_nationality !== passenger.nationality) {
                        
                        corrections.push({
                            passenger_name: passenger.passenger_name,
                            verified_data: {
                                name: corrected_name,
                                id_no: corrected_id,
                                nationality: corrected_nationality
                            }
                        });
                    }
                });
                
                frm.events.apply_corrections(frm, corrections);
                dialog.hide();
            }
        });
        
        dialog.show();
    },
    
    apply_corrections: function(frm, corrections) {
        corrections.forEach(function(correction) {
            frappe.call({
                method: 'verify_ocr_result',
                doc: frm.doc,
                args: {
                    passenger_name: correction.passenger_name,
                    verified_data: correction.verified_data
                },
                callback: function(r) {
                    if (r.message && r.message.success) {
                        frappe.show_alert({
                            message: __('OCR corrections saved and learned!'),
                            indicator: 'green'
                        });
                    }
                }
            });
        });
        
        frm.reload_doc();
    }
});

