frappe.ui.form.on("Vehicle Inspection Log", {
  onload(frm) {
    frm.trigger("prefill_checklist");
  },

  refresh(frm) {
    // Keep grid editable only for Status, but DO NOT hide Add Row buttons
    const grid = frm.fields_dict.items?.grid;
    if (!grid) return;

    // Do NOT do: grid.cannot_add_rows / cannot_delete_rows
    // Let buttons stay visible (your request)

    // Only status editable
    grid.toggle_enable("status", true);
    ["section", "item_en", "category", "item", "notes", "sort_order"].forEach((f) => {
      grid.toggle_enable(f, false);
    });
  },

  prefill_checklist(frm) {
    if (!frm.is_new()) return;

    // handle default not yet set on new doc
    if (frm.doc.auto_fill_checklist === 0) return;

    if (frm.doc.items && frm.doc.items.length) return;

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Vehicle Inspection Checklist Item",
        fields: ["name", "category", "sort_order", "item"],
        filters: { is_active: 1 },
        order_by: "category asc, sort_order asc, creation asc",
        limit_page_length: 500
      },
      callback: (r) => {
        const rows = r.message || [];
        if (!rows.length) return;

        frm.clear_table("items");

        rows.forEach((d) => {
          const row = frm.add_child("items");
          row.section = d.category || "";
          row.item_en = d.name;          // Link to master
          row.category = d.category || "";
          row.item = d.item || "";
          row.sort_order = d.sort_order || 0;
          row.status = "Sound | سليم";   // default
        });

        frm.refresh_field("items");
      }
    });
  }
